<script setup lang="ts">
import { computed,onScopeDispose,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { catalogApi,catalogScope,defaultProductConfiguration,type Product } from '../api/catalog'
import { errorMessage,isCancelled } from '../api/management'
import { useSessionStore } from '../stores/session'
import CatalogNavigation from '../components/CatalogNavigation.vue'
import StatePanel from '../components/StatePanel.vue'
import {useProductDirectory,categoryLabel} from '../api/directory'
import ProductConfigurationForm from '../components/ProductConfigurationForm.vue'
const route=useRoute(),router=useRouter(),session=useSessionStore()
const scope=catalogScope(route.meta.catalogPlatform===true,route.params.tenantId)
const writable=computed(()=>!!session.account?.platformAdmin || (route.meta.catalogPlatform!==true && ['OWNER','ADMIN'].includes((session.tenant?.id===route.params.tenantId ? session.tenant.role : undefined)||'')))
const rows=ref<Product[]>([]),query=ref(''),page=ref(1),total=ref(0),loading=ref(true),error=ref(''),show=ref(false),busy=ref(false),saveError=ref('')
const selectedCategory=ref('')
function chooseCategory(node:{value:string}){selectedCategory.value=node.value;page.value=1;void load()}
const code=ref(''),name=ref(''),description=ref(''),configuration=ref(defaultProductConfiguration())
const life=new AbortController();const {options:productCategories,items:directoryItems,error:directoryError}=useProductDirectory(scope,life.signal);let request=new AbortController(),revision=0
async function load(){request.abort();request=new AbortController();const current=++revision;loading.value=true;error.value='';rows.value=[];try{const data=await catalogApi.products(scope,query.value,page.value,request.signal,selectedCategory.value);if(current!==revision)return;rows.value=data.items;total.value=data.total}catch(e){if(current===revision&&!isCancelled(e))error.value=errorMessage(e)}finally{if(current===revision)loading.value=false}}
async function create(){if(busy.value)return;busy.value=true;saveError.value='';try{const p=await catalogApi.create(scope,{code:code.value,name:name.value,description:description.value,configuration:configuration.value},life.signal);show.value=false;await router.push(`${scope}/products/${p.id}`)}catch(e){if(!isCancelled(e))saveError.value=errorMessage(e)}finally{busy.value=false}}
onScopeDispose(()=>{revision++;request.abort();life.abort()});void load()
</script>
<template><CatalogNavigation/><div class="page-heading"><div><p class="eyebrow">PRODUCT CATALOG</p><h1>产品管理</h1></div><el-button v-if="writable&&session.can('product:write')" type="primary" @click="show=true;code='';name='';description='';saveError='';configuration={...defaultProductConfiguration(),category:selectedCategory.includes('-')?selectedCategory:''}">创建产品</el-button></div><div class="product-catalog-layout"><aside class="panel product-directory"><h2>产品目录</h2><el-button v-if="session.can('product:read')" link type="primary" @click="router.push(`${scope}/categories`)">管理目录</el-button><el-alert v-if="directoryError" :title="directoryError" type="error" :closable="false"/><p class="muted small">母婴电器 · 二级分类</p><el-tree :data="[{label:'全部产品',value:''},...productCategories]" node-key="value" :props="{label:'label',children:'children'}" default-expand-all highlight-current :current-node-key="selectedCategory" :expand-on-click-node="false" @node-click="chooseCategory"/></aside><section class="panel"><form class="tenant-context-toolbar" @submit.prevent="page=1;load()"><h2>{{selectedCategory?categoryLabel(directoryItems,selectedCategory):'全部产品'}} · {{total}}</h2><div class="tenant-search"><el-input v-model="query" maxlength="100" placeholder="搜索编码或名称" aria-label="搜索产品" clearable/><el-button native-type="submit">查询</el-button><el-button @click="load">刷新</el-button></div></form><div v-if="loading" class="tenant-context-loading"><el-skeleton :rows="5" animated/></div><StatePanel v-else-if="error" title="产品加载失败" :description="error"><el-button @click="load">重试</el-button></StatePanel><StatePanel v-else-if="!rows.length" title="暂无产品" description="创建产品后，编辑草稿并发布物模型，即可登记该产品的设备。"/><div v-else class="tenant-table"><el-table :data="rows"><el-table-column prop="name" label="产品名称" min-width="150"/><el-table-column v-if="route.meta.catalogPlatform" label="数据归属" min-width="150"><template #default="{row}">{{row.tenantId||'无租户'}}</template></el-table-column><el-table-column prop="code" label="产品编码" min-width="150"/><el-table-column label="产品品类" min-width="120"><template #default="{row}">{{categoryLabel(directoryItems,row.configuration?.category||'')}}</template></el-table-column><el-table-column label="设备类型" width="110"><template #default="{row}">{{({DIRECT:'直连设备',GATEWAY:'网关设备',CHILD:'网关子设备'} as Record<string,string>)[row.configuration?.deviceType]||'直连设备'}}</template></el-table-column><el-table-column label="最新版本" width="120"><template #default="{row}">{{row.latestVersion||'未发布'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'" effect="plain">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button type="primary" link @click="router.push(`${scope}/products/${row.id}`)">查看产品</el-button></template></el-table-column></el-table></div><div class="tenant-pagination"><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="(p:number)=>{page=p;load()}"/></div></section></div><el-dialog v-model="show" title="创建产品" width="min(760px,94vw)" :show-close="!busy" :close-on-click-modal="!busy" :close-on-press-escape="!busy"><form class="tenant-form" @submit.prevent="create"><label for="product-code">产品编码（必填）</label><el-input id="product-code" v-model="code" required aria-required="true" maxlength="64" placeholder="字母、数字、点、下划线或连字符" :disabled="busy"/><label for="product-name">产品名称（必填）</label><el-input id="product-name" v-model="name" required aria-required="true" maxlength="100" :disabled="busy"/><label for="product-description">产品描述（选填）</label><el-input id="product-description" v-model="description" type="textarea" maxlength="1000" :disabled="busy"/><ProductConfigurationForm v-model="configuration" :disabled="busy"/><el-alert v-if="saveError" :title="saveError" type="error" :closable="false"/><div class="tenant-form-actions"><el-button :disabled="busy" @click="show=false">取消</el-button><el-button type="primary" native-type="submit" :loading="busy" :disabled="!code||!name.trim()">创建产品</el-button></div></form></el-dialog></template>

<style scoped>.product-catalog-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:20px;align-items:start}.product-directory{padding:20px 14px;position:sticky;top:20px}.product-directory h2,.product-directory p{margin:0 8px 12px}.product-directory :deep(.el-tree-node__content){height:36px}.product-directory :deep(.is-current>.el-tree-node__content){color:var(--el-color-primary);background:var(--el-color-primary-light-9)}@media(max-width:900px){.product-catalog-layout{grid-template-columns:1fr}.product-directory{position:static}}</style>